// The app icons in public/ (generated by scripts/build-icons.mjs from the logo v2 symbol) and their tags.
import { test } from 'node:test'
import assert from 'node:assert/strict'
import { readFileSync } from 'node:fs'

const file = (name: string) => readFileSync(new URL(`../public/${name}`, import.meta.url))
const pngSize = (png: Buffer) => {
  assert.equal(png.subarray(1, 4).toString(), 'PNG')
  return [png.readUInt32BE(16), png.readUInt32BE(20)]
}

test('favicon.ico holds 16, 32 and 48 px PNG images', () => {
  const ico = file('favicon.ico')
  assert.equal(ico.readUInt16LE(2), 1)
  const count = ico.readUInt16LE(4)
  const sizes = Array.from({ length: count }, (_, index) => {
    const at = 6 + 16 * index
    const png = ico.subarray(ico.readUInt32LE(at + 12), ico.readUInt32LE(at + 12) + ico.readUInt32LE(at + 8))
    assert.deepEqual(pngSize(png), [ico[at], ico[at + 1]])
    return ico[at]
  })
  assert.deepEqual(sizes, [16, 32, 48])
})

test('touch, manifest and maskable icons have their sizes; the manifest lists them', () => {
  assert.deepEqual(pngSize(file('apple-touch-icon.png')), [180, 180])
  const manifest = JSON.parse(file('site.webmanifest').toString())
  assert.equal(manifest.name, '캡슐 CAPSULE')
  assert.equal(manifest.theme_color, '#0F0E17')
  for (const icon of manifest.icons) {
    const [width] = icon.sizes.split('x').map(Number)
    assert.deepEqual(pngSize(file(icon.src.slice(1))), [width, width], icon.src)
  }
})

test('index.html links the icons: SVG first choice, ICO fallback, touch icon, manifest', () => {
  const html = readFileSync(new URL('../index.html', import.meta.url), 'utf8')
  assert.match(html, /<link rel="icon" href="\/favicon\.ico" sizes="any" \/>/)
  assert.match(html, /<link rel="icon" type="image\/svg\+xml" href="\/favicon\.svg" \/>/)
  assert.match(html, /<link rel="apple-touch-icon" href="\/apple-touch-icon\.png" \/>/)
  assert.match(html, /<link rel="manifest" href="\/site\.webmanifest" \/>/)
  assert.match(html, /<meta name="theme-color" content="#0F0E17" \/>/)
})
